-- OPTIONAL DEMONSTRATION RECORDS. These are not official club times or locations.
-- Run after approving the first administrator. Add users to a Demo team in Administration to assign sample programmes.
-- Safe to rerun: fixed sample IDs use ON CONFLICT DO NOTHING.
begin;
do $$
declare actor uuid; monday date:=date_trunc('week',now() at time zone 'Europe/London')::date;
begin
select id into actor from public.profiles where approved and role in ('administrator','coach') order by created_at limit 1;
if actor is null then raise exception 'Create and approve the first administrator before seeding';end if;
end $$;
commit;
